import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { imageSize } from "image-size";

export const MAX_IMAGE_BYTES = 10 * 1024 * 1024;
const MAX_DIMENSION = 10_000;

// image-size type -> [file extension, content type]
const ALLOWED = {
  jpg: ["jpg", "image/jpeg"],
  png: ["png", "image/png"],
  webp: ["webp", "image/webp"],
  gif: ["gif", "image/gif"],
} as const;

const CONTENT_TYPES: Record<string, string> = Object.fromEntries(Object.values(ALLOWED));

// Stored names are generated by us: uuid + allowed extension. Anything else is rejected on read.
const FILE_NAME_RE = /^[0-9a-f-]{36}\.(jpg|png|webp|gif)$/;

export type InspectedImage = { ext: string; contentType: string; width: number; height: number };

/** Validate an upload by its bytes (not its claimed type) and read its dimensions. */
export function inspectImage(data: Uint8Array): InspectedImage | { error: string } {
  if (data.byteLength === 0) return { error: "빈 파일은 올릴 수 없어요." };
  if (data.byteLength > MAX_IMAGE_BYTES) return { error: "사진은 한 장에 10MB까지 올릴 수 있어요." };
  let info;
  try {
    info = imageSize(data);
  } catch {
    return { error: "사진 파일만 올릴 수 있어요." };
  }
  const allowed = ALLOWED[info.type as keyof typeof ALLOWED];
  if (!allowed) return { error: "JPG, PNG, WebP, GIF 사진만 올릴 수 있어요." };
  const { width = 0, height = 0 } = info;
  if (width < 1 || height < 1 || width > MAX_DIMENSION || height > MAX_DIMENSION) {
    return { error: "사진 크기를 확인해주세요." };
  }
  return { ext: allowed[0], contentType: allowed[1], width, height };
}

function uploadDir() {
  return path.resolve(process.env.UPLOAD_DIR ?? "uploads");
}

export async function saveImage(data: Uint8Array, ext: string): Promise<string> {
  const fileName = `${randomUUID()}.${ext}`;
  await mkdir(uploadDir(), { recursive: true });
  await writeFile(path.join(uploadDir(), fileName), data);
  return fileName;
}

export async function readImage(fileName: string): Promise<{ data: Buffer; contentType: string } | null> {
  if (!FILE_NAME_RE.test(fileName)) return null;
  try {
    const data = await readFile(path.join(uploadDir(), fileName));
    return { data, contentType: CONTENT_TYPES[fileName.split(".").pop()!] };
  } catch {
    return null;
  }
}

export async function deleteImages(fileNames: string[]) {
  await Promise.all(
    fileNames.filter((f) => FILE_NAME_RE.test(f)).map((f) => rm(path.join(uploadDir(), f), { force: true })),
  );
}

export const imageUrl = (fileName: string) => `/api/images/${fileName}`;
